class Solution {
private:
    long long zeta(long long x) {
        long long res = 0;
        while (x > 0) {
            res += x / 5;
            x /= 5;
        }
        return res;
    }
public:
    int preimageSizeFZF(int k) {
        long long left = 0, right = 5000000000LL;
        while (left < right) {
            long long mid = left + (right - left) / 2;
            if (zeta(mid) >= k) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }
        if (zeta(left) == k) return 5;
        return 0;
    }
};
